/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: CatalogReviewLookupBrief
 *   Functions: catalogReviewLookupBrief, catalogReviewLookupBriefOrNone
 *   Constants: CATALOG_REVIEW_LOOKUP_BRIEF_LIMITS, CATALOG_REVIEW_LOOKUP_BRIEF_PROJECTION
 * Internal
 *   Types: View, Candidate
 *   Functions: nextStep, fold, spaced, nameParts, pageTitle, tier, editionKey, releaseCount, fit, appliedAgain
 *   Constants: brackets
 * @end-catalog */

/**
 * The text-free brief of an existing-Album review's metadata lookup that the Web workbench card and the Album page's
 * open-completion note show: the run's state, its outcome, the lookup answers it waits for, the next step the review page offers
 * and how many releases may match. It reads the review's allowlisted lookup view (lookupView.ts) as the review page reads it: the
 * shared next step (web/src/features/admin/lookupNextStep.ts) and the review's possible matches and cause
 * (web/src/features/admin/reviewLookupStatus.ts, reviewLookupBrief.ts), repeated here because server code never imports the Web
 * client; test/administration/catalogReviewLookupBrief.test.ts runs both on the same records. Enums and two bounded counts, never
 * a title, name or query. Pure.
 */
import { catalogReviewDraftView } from '../import/adminImportDraftCompat';
import type { AdminImportDocument } from '../import/adminImportService';
import { catalogReviewLookupView, type CatalogReviewLookupView } from './lookupView';
import type { MetadataLookupRecord } from './metadataLookupRecord';

export type CatalogReviewLookupBrief = {
    /** The run's state; `failed` for a run that ended unavailable, stopped or superseded. */
    state: 'queued' | 'running' | 'retrying' | 'complete' | 'failed';
    /**
     * `active` while queued, running or retrying; `applied` once a release of this run is in the draft; `matched` while matching
     * releases wait for a choice, or after none was chosen; `possible` when nothing matched but the review page shows releases the
     * tracks may fit (or, for an Album without members, releases to choose from, when the run found any); `none` for no match, no
     * release or nothing to search; `unavailable` when MusicBrainz, its release details or the run did not finish.
     */
    outcome: 'active' | 'applied' | 'matched' | 'possible' | 'none' | 'unavailable';
    /** Open lookup answers as the review page counts them: unanswered conflicts of the applied candidate, plus one for a tie. */
    answers: number;
    /** What the review page asks for next: the free retry, choosing a release, or entering Disc and Track Numbers. */
    next: 'retry' | 'choose' | 'numbers' | null;
    /** For `possible`: the releases (editions grouped) the review page counts; 0 otherwise. */
    releases: number;
};
/** answers: 406 conflicts (REVIEW_LOOKUP_LIMITS.answers) plus a tie; releases: the view's 25 candidates. */
export const CATALOG_REVIEW_LOOKUP_BRIEF_LIMITS = Object.freeze({ answers: 407, releases: 25 });
/**
 * Fields of a stored record the view never reads (ranking evidence per member and per candidate, candidate proposals), left out
 * of the workbench and eligibility reads to keep them small.
 */
export const CATALOG_REVIEW_LOOKUP_BRIEF_PROJECTION = Object.freeze({
    'ranking.files': 0, 'ranking.candidates.proposal': 0, 'ranking.candidates.comparison.files': 0 });

type View = CatalogReviewLookupView;
type Candidate = View['candidates'][number];

/** The shared next step (web lookupNextStep.ts) of a view: its status key and whether the free retry is offered. */
function nextStep(view: View, available: boolean): { status: string; retry: boolean } {
    const applied = view.applied, tie = view.needsAnswer.tie;
    const unmatched = !view.groups.length && (applied?.run !== view.run || applied?.choice === 'none');
    const musicBrainzDown = view.issue === 'sourceUnavailable' || view.issue === 'sourceBusy';
    const [status, retry]: [string, boolean] = view.state === 'queued' || view.state === 'running' ? [view.itunes === 'running' ? 'lookup.active_itunes' : 'lookup.active', false]
        : view.state === 'retrying' ? [view.itunes === 'retrying' ? 'lookup.retrying_itunes' : 'lookup.retrying', true]
        : view.state === 'unavailable' ? [view.issue === 'notConfigured' ? 'lookup.not_configured' : 'lookup.unavailable', view.issue !== 'notConfigured']
        : view.state !== 'complete' ? [`lookup.${view.state}`, true]
        : unmatched && view.itunes === 'unavailable' && !musicBrainzDown ? ['lookup.itunes_unavailable', false]
        : unmatched && musicBrainzDown ? [view.candidates.some(candidate => candidate.status === 'incomplete') ? 'lookup.incomplete' : 'lookup.unavailable', true]
        : view.outcome === 'noRelease' || view.outcome === 'noQuery' ? [view.outcome === 'noQuery' ? 'lookup.no_query' : 'lookup.no_release', false]
        : tie ? ['lookup.tie', false]
        : view.groups.length === 1 && !view.preselection && view.disclosure?.partialComparison && applied?.run !== view.run ? ['lookup.single_choice', false]
        : applied?.run === view.run && applied.choice !== 'none' ? (applied.source !== 'itunes' ? ['lookup.applied', false]
            : applied.notChecked ? ['lookup.applied_itunes_unchecked', true] : ['lookup.applied_itunes', false])
        : view.groups.length ? ['lookup.applied_none', false]
        : view.candidates.some(candidate => candidate.status === 'incomplete') ? ['lookup.incomplete', true]
        : [applied?.run === view.run ? 'lookup.applied_none' : 'lookup.no_match', false];
    return { status, retry: retry && available };
}

const fold = (value: string) => value.normalize('NFKC').toLowerCase().trim();
const brackets = /[「」『』()[\]]/gu;
const spaced = (value: string) => value.replace(brackets, ' ').replace(/\s+/gu, ' ').trim();
const nameParts = (name: string) => {
    const folded = fold(name), parts = /^(.*?)\s*[-(]\s*(.+?)\s*[-)]$/u.exec(folded);
    return [spaced(folded), ...(parts ? parts.slice(1) : [])].filter(Boolean);
};
/** The review page's normalized title (web reviewLookupStatus.ts normalizedTitle), not the run's own comparison. */
function pageTitle(title: string, artists: readonly string[]): string {
    let value = spaced(fold(title.replace(/\s*／[^／]+$|\s+\/\s+[^/]+$/u, '') || title));
    for (const part of artists.flatMap(nameParts)) {
        if (value.startsWith(`${part} `)) value = value.slice(part.length + 1).trim();
        if (value.endsWith(` ${part}`)) value = value.slice(0, -part.length - 1).trim();
    }
    return value;
}
/** web titleTier. */
const tier = (candidate: string, searched: string): 'same' | 'similar' | 'other' => !candidate || !searched ? 'other'
    : candidate === searched ? 'same' : candidate.includes(searched) || searched.includes(candidate) ? 'similar' : 'other';
/** web editionKey: candidates sharing these values are editions of one release. */
const editionKey = (candidate: Candidate) => JSON.stringify([candidate.title, candidate.artist, candidate.label, candidate.date, candidate.barcode,
    candidate.catalogNumber, candidate.trackCount]);
const releaseCount = (candidates: readonly Candidate[]) => new Set(candidates.map(editionKey)).size;

/**
 * Where the shared step is no match (web reviewLookupFit): for an Album without members its same-title releases (needing a
 * choice), while the run found any release at all; else the releases the tracks fit (possible matches, else those whose titles
 * differ) and whether Disc and Track Numbers are needed; null for a real no match.
 */
function fit(view: View, members: number, searched: string, artists: readonly string[]): { releases: number; numbers: boolean } | null {
    const key = pageTitle(searched, artists), titleTier = (candidate: Candidate) => tier(pageTitle(candidate.title ?? '', artists), key);
    const fits = view.candidates.filter(candidate => candidate.status === 'unverified' || candidate.status === 'matching');
    const same = fits.filter(candidate => titleTier(candidate) === 'same');
    const possible = same.length ? same : fits.filter(candidate => titleTier(candidate) === 'similar');
    if (!members) return view.candidates.length ? { releases: releaseCount(possible), numbers: false } : null;
    const chosen = possible.length ? possible : fits.filter(candidate => !possible.includes(candidate));
    const pairings = chosen.map(candidate => candidate.comparison?.subset?.pairing), unknown = view.disclosure?.unknownLocalDurations ?? 0;
    const cause = unknown ? pairings.includes('unique') ? 'paired_durations' : 'durations'
        : pairings.includes('ambiguous') ? 'pairing' : pairings.includes('unique') ? 'release_durations' : null;
    return chosen.length && cause ? { releases: releaseCount(chosen), numbers: cause === 'durations' || cause === 'pairing' } : null;
}
/** A release this run applied for its Album values only whose pairing a saved number has since made single (web reviewAppliedAgain). */
const appliedAgain = (view: View, status: string) => {
    const applied = view.applied;
    return status === 'lookup.applied' && applied?.run === view.run && applied.choice === 'chosen' && applied.pairs === null
        && view.candidates.some(candidate => candidate.key === applied.candidateKey && candidate.comparison?.subset?.pairing === 'unique'
            && Boolean(candidate.comparison.trackCount.local));
};

/**
 * The brief of a review's stored lookup record, or null without a readable run (no record, or one this release cannot read, as
 * the review's lookup read shows none). `available`: whether lookup runs on this server, which the free retry needs.
 */
export function catalogReviewLookupBrief(record: MetadataLookupRecord | null, doc: AdminImportDocument, available: boolean): CatalogReviewLookupBrief | null {
    const view = record ? catalogReviewLookupView(record, doc) : null;
    if (!view) return null;
    // The draft the review detail shows: its title, primary Artists and members, as the review page reads them.
    const draft = catalogReviewDraftView(doc), submitted = view.input.submitted;
    const searched = submitted?.kind === 'album' ? submitted.text : draft.album.title;
    const artists = draft.album.artists.filter(entry => entry.role === 'primary').map(entry => entry.name);
    const { status, retry } = nextStep(view, available), needed = new Set(view.needsAnswer.conflicts);
    const answers = (view.needsAnswer.tie ? 1 : 0) + (view.applied?.conflicts.filter(conflict => needed.has(conflict.path)).length ?? 0);
    const active = view.state === 'queued' || view.state === 'running' || view.state === 'retrying';
    const state: CatalogReviewLookupBrief['state'] = active ? view.state as 'queued' | 'running' | 'retrying' : view.state === 'complete' ? 'complete' : 'failed';
    const brief = (outcome: CatalogReviewLookupBrief['outcome'], next: CatalogReviewLookupBrief['next'] = null, releases = 0): CatalogReviewLookupBrief =>
        ({ state, outcome, answers, next, releases });
    if (active) return brief('active');
    if (appliedAgain(view, status)) return brief('applied', 'choose');
    const found = status === 'lookup.no_match' || status === 'lookup.itunes_unavailable' ? fit(view, draft.tracks.length, searched, artists) : null;
    if (found) return brief('possible', found.numbers ? 'numbers' : 'choose', found.releases);
    return status === 'lookup.applied' || status === 'lookup.applied_itunes' ? brief('applied')
        : status === 'lookup.applied_itunes_unchecked' ? brief('applied', retry ? 'retry' : null)
        : status === 'lookup.tie' || status === 'lookup.single_choice' ? brief('matched', 'choose')
        : status === 'lookup.applied_none' ? brief('matched')
        : ['lookup.no_match', 'lookup.itunes_unavailable', 'lookup.no_release', 'lookup.no_query'].includes(status) ? brief('none')
        : brief('unavailable', retry ? 'retry' : null);
}

/**
 * The brief, or null where reading the record throws (a malformed or older stored record): a convenience that degrades to no
 * lookup status, so one such review never fails the whole Album completions queue or the Album page's eligibility read.
 */
export function catalogReviewLookupBriefOrNone(...args: Parameters<typeof catalogReviewLookupBrief>): CatalogReviewLookupBrief | null {
    try { return catalogReviewLookupBrief(...args); } catch { return null; }
}
